// Guardian Mobile — design tokens.
// Generated by hand from the "Guardian Mobile" design system (tokens.json).
// Keep names identical to the design system so design ↔ code stay in sync.
import 'package:flutter/material.dart';

/// Colour tokens for one theme. Read them with `context.gm` (see guardian_theme.dart).
@immutable
class GColors extends ThemeExtension<GColors> {
  const GColors({
    required this.bg,
    required this.surface,
    required this.surfaceSunken,
    required this.surfaceRaised,
    required this.border,
    required this.borderStrong,
    required this.ink,
    required this.inkMuted,
    required this.inkSubtle,
    required this.brand,
    required this.brandPressed,
    required this.onBrand,
    required this.brandSoft,
    required this.brandInk,
    required this.danger,
    required this.dangerPressed,
    required this.onDanger,
    required this.dangerSoft,
    required this.dangerInk,
    required this.warning,
    required this.warningSoft,
    required this.warningInk,
    required this.info,
    required this.infoSoft,
    required this.scrim,
  });

  final Color bg, surface, surfaceSunken, surfaceRaised, border, borderStrong;
  final Color ink, inkMuted, inkSubtle;
  final Color brand, brandPressed, onBrand, brandSoft, brandInk;
  final Color danger, dangerPressed, onDanger, dangerSoft, dangerInk;
  final Color warning, warningSoft, warningInk, info, infoSoft, scrim;

  static const light = GColors(
    bg: Color(0xFFF3F6F4),
    surface: Color(0xFFFFFFFF),
    surfaceSunken: Color(0xFFEBF0ED),
    surfaceRaised: Color(0xFFFFFFFF),
    border: Color(0xFFDFE6E2),
    borderStrong: Color(0xFF8C9C95),
    ink: Color(0xFF0E1A15),
    inkMuted: Color(0xFF56665F),
    inkSubtle: Color(0xFF7D8C86),
    brand: Color(0xFF047A55),
    brandPressed: Color(0xFF035E42),
    onBrand: Color(0xFFFFFFFF),
    brandSoft: Color(0xFFE2F4EB),
    brandInk: Color(0xFF04603F),
    danger: Color(0xFFC62A31),
    dangerPressed: Color(0xFFA31D24),
    onDanger: Color(0xFFFFFFFF),
    dangerSoft: Color(0xFFFDECED),
    dangerInk: Color(0xFF9F1A21),
    warning: Color(0xFFB45309),
    warningSoft: Color(0xFFFEF3E2),
    warningInk: Color(0xFF8A3F06),
    info: Color(0xFF1F5FD6),
    infoSoft: Color(0xFFE7EFFF),
    scrim: Color(0x73060E0B),
  );

  static const dark = GColors(
    bg: Color(0xFF0B110F),
    surface: Color(0xFF131B18),
    surfaceSunken: Color(0xFF1A2420),
    surfaceRaised: Color(0xFF1C2622),
    border: Color(0xFF26322D),
    borderStrong: Color(0xFF5C6E66),
    ink: Color(0xFFECF3EF),
    inkMuted: Color(0xFF9BADA5),
    inkSubtle: Color(0xFF6F8079),
    brand: Color(0xFF2FBF8F),
    brandPressed: Color(0xFF5DD4A9),
    onBrand: Color(0xFF03140E),
    brandSoft: Color(0xFF12302A),
    brandInk: Color(0xFF74E3B9),
    danger: Color(0xFFFF6B6F),
    dangerPressed: Color(0xFFFF9396),
    onDanger: Color(0xFF1D0507),
    dangerSoft: Color(0xFF3A1518),
    dangerInk: Color(0xFFFFA3A6),
    warning: Color(0xFFF5B454),
    warningSoft: Color(0xFF36280F),
    warningInk: Color(0xFFF8C77A),
    info: Color(0xFF80AAFF),
    infoSoft: Color(0xFF16233F),
    scrim: Color(0x99000000),
  );

  @override
  GColors copyWith() => this;

  @override
  GColors lerp(GColors? other, double t) {
    if (other == null) return this;
    Color l(Color a, Color b) => Color.lerp(a, b, t)!;
    return GColors(
      bg: l(bg, other.bg), surface: l(surface, other.surface),
      surfaceSunken: l(surfaceSunken, other.surfaceSunken), surfaceRaised: l(surfaceRaised, other.surfaceRaised),
      border: l(border, other.border), borderStrong: l(borderStrong, other.borderStrong),
      ink: l(ink, other.ink), inkMuted: l(inkMuted, other.inkMuted), inkSubtle: l(inkSubtle, other.inkSubtle),
      brand: l(brand, other.brand), brandPressed: l(brandPressed, other.brandPressed), onBrand: l(onBrand, other.onBrand),
      brandSoft: l(brandSoft, other.brandSoft), brandInk: l(brandInk, other.brandInk),
      danger: l(danger, other.danger), dangerPressed: l(dangerPressed, other.dangerPressed), onDanger: l(onDanger, other.onDanger),
      dangerSoft: l(dangerSoft, other.dangerSoft), dangerInk: l(dangerInk, other.dangerInk),
      warning: l(warning, other.warning), warningSoft: l(warningSoft, other.warningSoft), warningInk: l(warningInk, other.warningInk),
      info: l(info, other.info), infoSoft: l(infoSoft, other.infoSoft), scrim: l(scrim, other.scrim),
    );
  }
}

/// Spacing scale (space-1 … space-12).
abstract final class GSpace {
  static const s1 = 4.0, s2 = 8.0, s3 = 12.0, s4 = 16.0, s5 = 20.0, s6 = 24.0, s8 = 32.0, s12 = 48.0;
}

/// Corner radii.
abstract final class GRadius {
  static const sm = 10.0, md = 14.0, lg = 20.0, xl = 28.0, pill = 999.0;
  static BorderRadius get rMd => BorderRadius.circular(md);
  static BorderRadius get rLg => BorderRadius.circular(lg);
}

/// Motion tokens. Use `GMotion.of(context)` to respect "Reduce motion".
abstract final class GMotion {
  static const instant = Duration(milliseconds: 90);
  static const fast = Duration(milliseconds: 160);
  static const base = Duration(milliseconds: 260);
  static const slow = Duration(milliseconds: 380);
  static const stagger = Duration(milliseconds: 45);
  static const pulse = Duration(milliseconds: 1800);

  static const standard = Cubic(0.2, 0, 0, 1);
  static const enter = Cubic(0.05, 0.7, 0.1, 1);
  static const exit = Cubic(0.3, 0, 0.8, 0.15);
  static const spring = Cubic(0.34, 1.56, 0.64, 1);

  /// True when the user asked the OS to reduce animations.
  static bool reduced(BuildContext context) => MediaQuery.maybeDisableAnimationsOf(context) ?? false;

  /// A duration that collapses to zero under reduced motion.
  static Duration d(BuildContext context, Duration value) => reduced(context) ? Duration.zero : value;
}
